{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Untie history and candidate item embeddings at the current width, initializing the candidate table from the history table. Both tables train jointly within each category's single SASRec model. This may reduce conflict between encoding histories and predicting targets while preserving dot-product scoring, features, topology, loss, and optimizer.",
      "edits": [
        {
          "find": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.item_emb.weight.data.normal_(0.0, 1.0)\n        self.pos_emb = nn.Embedding(maxlen, hidden_units)",
          "replace": "        self.item_emb = nn.Embedding(itemnum + 1, hidden_units, padding_idx=0)\n        with torch.no_grad():\n            self.item_emb.weight.normal_(0.0, 1.0)\n            self.item_emb.weight[0].zero_()\n        self.output_item_emb = nn.Embedding(\n            itemnum + 1, hidden_units, padding_idx=0,\n            _weight=self.item_emb.weight.detach().clone(),\n        )\n        self.pos_emb = nn.Embedding(maxlen, hidden_units)"
        },
        {
          "find": "        pos_embs = self.item_emb(pos)\n        neg_embs = self.item_emb(neg)",
          "replace": "        pos_embs = self.output_item_emb(pos)\n        neg_embs = self.output_item_emb(neg)"
        },
        {
          "find": "        item_embs = self.item_emb(candidates)\n        return item_embs.matmul(final_feat.unsqueeze(-1)).squeeze(-1)",
          "replace": "        item_embs = self.output_item_emb(candidates)\n        return item_embs.matmul(final_feat.unsqueeze(-1)).squeeze(-1)"
        },
        {
          "find": "            \"input_feature\": \"causal_prefix_repeat_v1\",\n            \"hidden_units\": HIDDEN_UNITS,",
          "replace": "            \"input_feature\": \"causal_prefix_repeat_v1\",\n            \"embedding_representation\": \"untied_input_output_v1\",\n            \"hidden_units\": HIDDEN_UNITS,"
        },
        {
          "find": "        # The imported SASRec computes causal prefix-repeat scaling in log2feats.\n        _metas[ds] = meta",
          "replace": "        if meta.get(\"embedding_representation\") != \"untied_input_output_v1\":\n            raise ValueError(f\"Unexpected embedding representation for {ds}\")\n        # The imported SASRec includes both jointly trained embedding tables.\n        _metas[ds] = meta"
        }
      ]
    }
  ],
  "change_summary": "Untied input and candidate embeddings with identical initialization and zero padding rows. Updated training scores, inference scores, and predictor metadata validation; existing strict checkpoint loading restores both tables in one SASRec model per category."
}
